      "content": "{\n  \"name\": \"fnos-cli-skill\",\n  \"version\": \"0.6.2\",\n  \"private\": true,\n  \"description\": \"fnOS Skill and DSH bridge for the latest fnOS CLI package\",\n  \"homepage\": \"https://fnnas.com/\",\n  \"type\": \"module\",\n  \"main\": \"index.mjs\",\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/fnnas-labs/fnos-cli-skill.git\"\n  },\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"dependencies\": {\n    \"@fnnas-labs/fnos-cli\": \"latest\"\n  },\n  \"files\": [\n    \"index.mjs\",\n    \"cordis.patch.yml\",\n    \"npm/dsh.mjs\",\n    \"skills/**\",\n    \"LICENSE\"\n  ]\n}\n"
