      "path": "skills/fnos-cli/scripts/fnos-cli",
      "content": "#!/bin/sh\n# Generated from the packaged runtime manifest; no Node/npm required.\nset -eu\nORIGINAL_UMASK=$(umask)\numask 077\nCOMMAND='fnos-cli'\nVERSION='0.6.2'\nPRODUCT='fnos'\nREPOSITORY='fnnas-labs/fnos-cli-skill'\nMANIFEST_HASH='bb5a171b24d3a7e69ec8144c0f2733222f737168e7999a76dc3fe4683b6cc707'\nfail() { printf '%s\\n' \"$*\" >&2; exit 1; }\nSCRIPT_DIR=$(CDPATH= cd -- \"$(dirname -- \"$0\")\" && pwd)\nfor tool in awk wc tr uname; do command -v \"$tool\" >/dev/null 2>&1 || fail \"Missing required tool: $tool\"; done\nif command -v sha256sum >/dev/null 2>&1; then HASH_TOOL=sha256sum\nelif command -v shasum >/dev/null 2>&1; then HASH_TOOL=shasum\nelse fail 'A SHA-256 tool is required (sha256sum or shasum).'; fi\nhash_file() {\n if [ \"$HASH_TOOL\" = sha256sum ]; then sha256sum < \"$1\"; else shasum -a 256 < \"$1\"; fi | awk '{print $1}'\n}\n[ -f \"$SCRIPT_DIR/../runtime-manifest.json\" ] && [ ! -L \"$SCRIPT_DIR/../runtime-manifest.json\" ] || fail 'Missing regular runtime manifest.'\n[ \"$(hash_file \"$SCRIPT_DIR/../runtime-manifest.json\")\" = \"$MANIFEST_HASH\" ] || fail 'Runtime manifest SHA256 mismatch.'\ncase \"$(uname -s):$(uname -m)\" in\n Darwin:arm64) PLATFORM=darwin-arm64 ;; Darwin:x86_64) PLATFORM=darwin-x64 ;;\n Linux:aarch64|Linux:arm64) PLATFORM=linux-arm64 ;; Linux:x86_64) PLATFORM=linux-x64 ;;\n *) fail 'Unsupported platform for this Skill.' ;;\nesac\ncase \"$PLATFORM\" in\n  darwin-arm64) ASSET='fnos-cli-0.6.2-darwin-arm64.gz'; ARCHIVE_SIZE=3179654; ARCHIVE_HASH=27d34ccaa362af76b7166a7c65f6c9267540c3efac67835158f8ceb382649122; BINARY_SIZE=8095136; BINARY_HASH=a0a68f3e24d946300b3a770db8d6616709fd047def2e45db2573d026cd87d13d ;;\n  darwin-x64) ASSET='fnos-cli-0.6.2-darwin-x64.gz'; ARCHIVE_SIZE=3257605; ARCHIVE_HASH=9b83a262197e258c6aaf943a24ec22b3352a82187d99e401d2c99aaa219efbea; BINARY_SIZE=8812952; BINARY_HASH=d2228a8ff68174a215b044611bd855794eaff1e130dfc7a1e52f7189d6c5c450 ;;\n  linux-arm64) ASSET='fnos-cli-0.6.2-linux-arm64.gz'; ARCHIVE_SIZE=2989593; ARCHIVE_HASH=db7d7a1ecac51bf1213b1b3a7eee77e14b5d16604ace00f83ba6587dad649ebc; BINARY_SIZE=6556400; BINARY_HASH=be0ae717c115b3f621ef18a12b884684b062e58ec796b0d018d7ab0c1d604e0c ;;\n  linux-x64) ASSET='fnos-cli-0.6.2-linux-x64.gz'; ARCHIVE_SIZE=3129409; ARCHIVE_HASH=f3233408662bf667355135771ce0d6db856ef334f16c5a552a53970976ffdc79; BINARY_SIZE=7643304; BINARY_HASH=08e6cd9f3017ce55b6d864ab304aba9d054b6a2af9d421a648e4d13ac62b0572 ;;\nesac\n# Preserve the independent Skill's existing capability boundary.\nskip=0\nfor arg do\n if [ \"$skip\" = 1 ]; then skip=0; continue; fi\n case \"$arg\" in\n  --host|--port|--profile|--scheme) skip=1 ;;\n  --*) ;;\n  media) printf '%s\\n' 'Media commands are not available in this skill package.' >&2; exit 2 ;;\n  *) break ;;\n esac\ndone\ncase \"$PLATFORM\" in\n darwin-*) BASE=\"${HOME:?HOME is required}/Library/Caches\" ;;\n *) BASE=${XDG_CACHE_HOME:-\"${HOME:?HOME is required}/.cache\"} ;;\nesac\ncase \"$BASE\" in /*) ;; *) fail 'User cache directory must be an absolute path.' ;; esac\nCACHE=\"$BASE/$COMMAND/$VERSION/$PLATFORM\"\nBINARY=\"$CACHE/$COMMAND\"\nLOCK=\"$CACHE.lock\"\n# Check every existing ancestor; mkdir -p by itself follows symlinks.\nsafe_directory() {\n [ ! -L \"$1\" ] || fail \"Unsafe runtime cache directory: $1\"\n if [ -e \"$1\" ]; then [ -d \"$1\" ] || fail \"Not a runtime directory: $1\"; return; fi\n parent=$(dirname -- \"$1\")\n [ \"$parent\" = \"$1\" ] || safe_directory \"$parent\"\n mkdir \"$1\" 2>/dev/null || [ -d \"$1\" ] || fail \"Cannot create runtime directory: $1\"\n [ ! -L \"$1\" ] || fail \"Unsafe runtime cache directory: $1\"\n}\n# Recursion uses positional parameters, not shared local state.\ncheck_ancestors() {\n [ ! -L \"$1\" ] || fail \"Unsafe runtime cache directory: $1\"\n [ \"$1\" = / ] && return\n check_ancestors \"$(dirname -- \"$1\")\"\n}\ncheck_ancestors \"$BASE/$COMMAND/$VERSION\"\nsafe_directory \"$BASE/$COMMAND/$VERSION\"\nsize_file() { wc -c < \"$1\" | tr -d '[:space:]'; }\nverify_file() {\n [ -f \"$1\" ] && [ ! -L \"$1\" ] || fail \"Not a regular runtime file: $1\"\n [ \"$(size_file \"$1\")\" = \"$2\" ] && [ \"$(hash_file \"$1\")\" = \"$3\" ] || fail \"Runtime SHA256 mismatch: $1. Remove its cache directory after confirming no initialization is running, then retry.\"\n}\nready() {\n [ ! -L \"$CACHE\" ] || fail \"Unsafe runtime cache: $CACHE\"\n [ -e \"$CACHE\" ] || return 1\n [ -d \"$CACHE\" ] && [ -f \"$BINARY\" ] || fail \"Incomplete runtime cache: $CACHE. Remove it after confirming no initialization is running, then retry.\"\n verify_file \"$BINARY\" \"$BINARY_SIZE\" \"$BINARY_HASH\"\n [ -x \"$BINARY\" ] || fail \"Runtime is not executable: $BINARY\"\n}\nlaunch() { umask \"$ORIGINAL_UMASK\"; export TRIM_CLI_DISTRIBUTION=\"$PRODUCT\"; exec \"$BINARY\" \"$@\"; }\nif ready; then launch \"$@\"; fi\nfor tool in curl gzip head mkfifo od sed mkdir chmod rm mv cat sleep; do command -v \"$tool\" >/dev/null 2>&1 || fail \"Missing required tool: $tool\"; done\nwaited=0\nwhile ! mkdir \"$LOCK\" 2>/dev/null; do\n [ ! -L \"$LOCK\" ] || fail \"Unsafe initialization lock: $LOCK\"\n [ ! -e \"$LOCK\" ] || [ -d \"$LOCK\" ] || fail \"Cannot create initialization lock: $LOCK\"\n if ready; then launch \"$@\"; fi\n [ \"$waited\" -lt 60 ] || fail \"CLI initialization is locked: $LOCK. Remove this lock only after confirming its initializer has stopped.\"\n sleep 1; waited=$((waited+1))\ndone\nchmod 700 \"$LOCK\" || { rm -rf \"$LOCK\"; fail \"Cannot secure initialization lock.\"; }\nOWNER=\"$$-$(od -An -N16 -tx1 /dev/urandom | tr -d ' \\n')\"\nprintf '%s\\n' \"$OWNER\" > \"$LOCK/owner\" || { rm -rf \"$LOCK\"; fail \"Cannot record initialization owner.\"; }\nproducer=; consumer=; timer=; writer=\ncleanup() {\n for job in \"$producer\" \"$consumer\" \"$timer\" \"$writer\"; do\n  if [ -n \"$job\" ]; then kill -KILL \"$job\" 2>/dev/null || :; wait \"$job\" 2>/dev/null || :; fi\n done\n if [ -d \"$LOCK\" ] && [ ! -L \"$LOCK\" ] && [ -f \"$LOCK/owner\" ] && [ ! -L \"$LOCK/owner\" ] && [ \"$(cat \"$LOCK/owner\")\" = \"$OWNER\" ]; then rm -rf \"$LOCK\"; fi\n}\ntrap cleanup EXIT\nterminate() { cleanup; trap - EXIT INT TERM HUP; kill -s \"$1\" \"$$\"; }\ntrap 'terminate INT' INT\ntrap 'terminate TERM' TERM\ntrap 'terminate HUP' HUP\nif ready; then cleanup; trap - EXIT INT TERM HUP; launch \"$@\"; fi\nprintf 'Downloading %s %s (%s)...\\n' \"$COMMAND\" \"$VERSION\" \"$PLATFORM\" >&2\n# A restricted URL parser: never evaluate user configuration as shell code.\n# mode=registry also removes default ports/trailing slashes and skips npmjs.\nurl_parse() {\n printf '%s\\n' \"$1\" | awk -v mode=\"$2\" '\n function bad(){invalid=1;exit 1}\n NR>1 {bad()}\n /[[:space:]\\\\]/ {bad()}\n {s=$0; if(tolower(substr(s,1,8))!=\"https://\")bad(); s=substr(s,9);\n  if(s==\"\" || s~/^[\\/?#]/)bad(); a=s; sub(/[\\/?#].*$/,\"\",a); p=substr(s,length(a)+1);\n  if(a~/@/ || (mode==\"registry\" && p~/[?#]/))bad(); a=tolower(a);\n  port=\"\"; host=a;\n  if(a~/^\\[/){i=index(a,\"]\");if(!i)bad();host=substr(a,1,i);tail=substr(a,i+1);if(tail!=\"\" && tail!~/^:[0-9]+$/)bad();port=substr(tail,2);if(host!~/^\\[[0-9a-f:.]+\\]$/)bad()}\n  else {if(a~/[^a-z0-9.:-]/)bad(); n=split(a,parts,\":\");if(n>2 || parts[1]==\"\")bad();host=parts[1];if(n==2){port=parts[2];if(port!~/^[0-9]+$/)bad()}}\n  if(port!=\"\" && (port+0>65535 || port+0<0))bad(); if(port!=\"\")port=sprintf(\"%d\",port);\n  a=host;if(port!=\"\" && port!=\"443\")a=a \":\" port;\n  if(mode==\"registry\"){if(host==\"registry.npmjs.org\")bad();sub(/\\/+$/,\"\",p)}\n  result=\"https://\" a p;\n }\n END {if(!invalid && NR==1)print result}'\n}\nREGISTRY=\nif [ \"${npm_config_registry+x}\" = x ]; then REGISTRY=$npm_config_registry\nelif command -v npm >/dev/null 2>&1; then\n # npm alone interprets its user/project config; stop reading it after 5 seconds.\n npm config get registry > \"$LOCK/registry\" 2>/dev/null & producer=$!\n (sleep 5; kill \"$producer\" 2>/dev/null || :) >/dev/null 2>&1 & timer=$!\n if wait \"$producer\"; then REGISTRY=$(cat \"$LOCK/registry\"); fi\n producer=; kill \"$timer\" 2>/dev/null || :; wait \"$timer\" 2>/dev/null || :; timer=\nfi\nCUSTOM=$(url_parse \"$REGISTRY\" registry) || CUSTOM=\nPUBLIC=\"https://registry.npmmirror.com/-/binary/$COMMAND/v$VERSION/$ASSET\"\n[ -z \"$CUSTOM\" ] || CUSTOM=\"$CUSTOM/-/binary/$COMMAND/v$VERSION/$ASSET\"\n# Resolve relative Location values without allowing an HTTP/userinfo redirect.\nredirect_url() {\n case \"$2\" in\n  [Hh][Tt][Tt][Pp][Ss]://*) url_parse \"$2\" redirect ;;\n  //*) url_parse \"https:$2\" redirect ;;\n  \\?*) previous=${1%%\\?*}; url_parse \"$previous$2\" redirect ;;\n  /*) origin=${1#https://}; origin=${origin%%/*}; url_parse \"https://$origin$2\" redirect ;;\n  *) case \"$2\" in *:*) return 1;; esac; previous=${1%%\\?*}; url_parse \"${previous%/*}/$2\" redirect ;;\n esac\n}\n# FIFO sinks bound unknown-length responses even on older curl implementations.\n# Child PIDs remain owned by this shell so signal cleanup closes the transport.\ndownload_source() {\n url=$1; hops=0\n while :; do\n  rm -f \"$LOCK/stream\" \"$LOCK/payload.gz\" \"$LOCK/headers\" \"$LOCK/status\" || fail \"Cannot reset download files.\"\n  : > \"$LOCK/headers\" || fail \"Cannot create download headers.\"\n  : > \"$LOCK/status\" || fail \"Cannot create download status.\"\n  mkfifo \"$LOCK/stream\" || fail 'Cannot create download stream.'\n  (trap - EXIT INT TERM HUP; exec head -c \"$((ARCHIVE_SIZE+1))\" < \"$LOCK/stream\" > \"$LOCK/payload.gz\") & consumer=$!\n  curl -q --silent --fail --proto '=https' --connect-timeout 10 --max-time 30 --max-filesize \"$((ARCHIVE_SIZE+1))\" --user-agent platform-cli-bootstrap --header 'Accept: application/octet-stream' --dump-header \"$LOCK/headers\" --write-out '%{http_code}' --output \"$LOCK/stream\" \"$url\" > \"$LOCK/status\" 2>/dev/null & producer=$!\n  rc=0; wait \"$producer\" || rc=$?; producer=\n  # Curl may finish without opening its output (e.g. an HTTP error).\n  # A zero-b