/stream\" > \"$LOCK/ready/$COMMAND\") & consumer=$!\n(trap - EXIT INT TERM HUP; exec gzip -dc \"$LOCK/payload.gz\" > \"$LOCK/stream\" 2>/dev/null) & producer=$!\nrc=0; wait \"$producer\" || rc=$?; producer=\nsink=0; wait \"$consumer\" || sink=$?; consumer=\n[ \"$(size_file \"$LOCK/ready/$COMMAND\")\" -le \"$BINARY_SIZE\" ] || fail 'Runtime binary exceeds its fixed size.'\n[ \"$rc\" -eq 0 ] && [ \"$sink\" -eq 0 ] || fail 'Cannot decompress runtime asset.'\nverify_file \"$LOCK/ready/$COMMAND\" \"$BINARY_SIZE\" \"$BINARY_HASH\"\nchmod 755 \"$LOCK/ready/$COMMAND\"\n[ -x \"$LOCK/ready/$COMMAND\" ] || fail 'Runtime is not executable.'\n[ ! -e \"$CACHE\" ] && [ ! -L \"$CACHE\" ] || fail \"Runtime cache appeared during initialization: $CACHE\"\nmv \"$LOCK/ready\" \"$CACHE\"\ncleanup\ntrap - EXIT INT TERM HUP\nlaunch \"$@\"\n"
