  try { fs.mkdirSync(directory); if(process.platform!=='win32') fs.chmodSync(directory,0o700); }
  catch(error) { if(error.code!=='EEXIST') throw error; }
  if(!fs.lstatSync(directory).isDirectory()) throw new Error(`Runtime cache is not a regular directory: ${directory}`);
}

function ensureDirectoryTree(directory) {
  const parent=path.dirname(directory);
  if(parent===directory) {
    if(!fs.lstatSync(directory).isDirectory()) throw new Error(`Unsafe runtime cache: ${directory}`);
